39	    let ini = "registry=https://r.example\n";
40	    let auth = NpmrcAuth::from_ini::<NoEnv>(ini, Path::new(""));
41	    assert_eq!(auth.registry.as_deref(), Some("https://r.example"));
42	
43	    let mut config = Config::new();
44	    auth.apply_to::<NoEnv>(&mut config);
