58	    // These are all project-structural settings that pnpm 11 only reads
59	    // from pnpm-workspace.yaml now. Writing them to .npmrc should be a
60	    // no-op.
61	    //
62	    // `Config::new()` reads `PNPM_HOME` / `XDG_DATA_HOME` via the
63	    // SmartDefault expression on `Config::store_dir` —
64	    // `default_store_dir::<Host, _, _, _>(home::home_dir,
65	    // env::current_dir)` — to compute `store_dir`. Both values come
66	    // from the real process environment, but no other test in this
67	    // crate mutates them anymore — the per-branch tests in
68	    // `defaults::tests` and `lib::tests` drive `default_store_dir`
69	    // through the dependency-injection seam (pnpm/pacquet#339,
70	    // pnpm/pnpm#11708, pnpm/pacquet#343) with fake `Sys` providers,
71	    // so the two `Config::new()` snapshots compared below observe
72	    // the same env-derived `store_dir` even under nextest's
